<?php
namespace App\Http\Controllers;use App\Http\Requests\BookingRequest;use App\Models\Booking;use App\Models\Service;use Illuminate\Http\Request;
class BookingController extends Controller{public function index(){ $bookings=auth()->user()->customerBookings()->with(['service','provider','payment','review'])->latest()->paginate(10);return view('bookings.customer',compact('bookings'));}public function store(BookingRequest $r){$service=Service::where('is_active',true)->findOrFail($r->service_id);$b=Booking::create(['customer_id'=>auth()->id(),'provider_id'=>$service->provider_id,'service_id'=>$service->id,'booking_date'=>$r->booking_date,'booking_time'=>$r->booking_time,'address'=>$r->address,'amount'=>$service->price,'customer_note'=>$r->customer_note]);return redirect()->route('payments.show',$b)->with('success','Booking created. Complete payment to confirm it.');}public function show(Booking $booking){$this->authorizeCustomerOrProvider($booking);$booking->load('service','customer','provider','payment','review');return view('bookings.show',compact('booking'));}public function cancel(Booking $booking){abort_unless($booking->customer_id===auth()->id(),403);if(!in_array($booking->status,['pending','confirmed'],true)){return back()->with('error','This booking cannot be cancelled.');}$booking->update(['status'=>'cancelled']);return back()->with('success','Booking cancelled.');}private function authorizeCustomerOrProvider(Booking $b){abort_unless(in_array(auth()->id(),[$b->customer_id,$b->provider_id])||auth()->user()->isAdmin(),403);}}
